/* data/learn-c/phy-12-16.js - GENERATED by tools/build_learn.py from data/learn/summaries/phy-12-16.json (our own words;
 * the notes of one chapter, loaded when the chapter is opened). Do not edit by hand. */
(window.LEARN_C = window.LEARN_C || {})["phy-12-16"] = {"16.1":{"s":"A p-n junction diode conducts when forward biased and almost blocks current when reverse biased, so it acts like a switch. Mains power is AC, but most electronic gadgets need DC. A power supply therefore uses a transformer, a diode rectifier (AC to pulsating DC), a filter that removes the ripple, and a voltage regulator that keeps the output steady.","w":["A half wave rectifier gives output pulses at the input frequency; a full wave rectifier at twice the input frequency (100 Hz from 50 Hz mains)."]},"16.2":{"s":"A rectifier changes AC into DC, using the fact that a p-n junction diode conducts in one direction only. A half wave rectifier uses one diode and passes only the positive half cycles. A full wave rectifier uses two diodes on a centre-tapped transformer and uses both half cycles, so it is more efficient. The output still has a small AC part, the ripple, which a filter (a capacitor across the load) reduces.","f":[{"x":"Ripple factor = (r.m.s. value of the AC component)/(value of the DC component)","n":"A smaller ripple factor means a better rectifier.","r":"Balbharati Physics XII, 16.2, p.346"},{"x":"f_out = f_in (half wave), f_out = 2*f_in (full wave)","n":"Output frequency: 50 Hz input gives 50 Hz from a half wave and 100 Hz from a full wave rectifier.","r":"Balbharati Physics XII, 16.2, p.346"}],"w":["The book gives the largest efficiency as 40.6% for a half wave and 81.2% for a full wave rectifier.","A full wave rectifier needs a centre-tapped transformer and two diodes (or a bridge of four)."]},"16.3":{"s":"Special purpose diodes. A Zener diode is heavily doped and is used in reverse breakdown, where its voltage stays almost constant, so it works as a voltage regulator. A photodiode is used in reverse bias; light makes its reverse current grow in proportion to the light. A solar cell turns light into electrical power with no bias at all. An LED gives out light when forward biased.","f":[{"x":"P_Z = I_Z(max)*V_Z","n":"Maximum power rating of a Zener diode.","r":"Balbharati Physics XII, 16.3, p.349"},{"x":"R_d = (maximum reverse voltage)/(dark current)","n":"Dark resistance of a photodiode (no light falling on it).","r":"Balbharati Physics XII, 16.3, p.352"}],"w":["Zener diode and photodiode work in REVERSE bias; an LED in FORWARD bias; a solar cell needs no bias.","In a Zener regulator the series resistor takes up the change in input voltage; the load voltage stays at the Zener voltage.","Printed p.354 calls Voc × Isc the maximum power. It is not: the power is zero at both ends, and the maximum is Vm × Im at the knee of the I-V curve, always below Voc × Isc."]},"16.4":{"s":"A bipolar junction transistor has three regions, emitter, base and collector, forming two back-to-back p-n junctions (n-p-n or p-n-p). The emitter is heavily doped, the base is very thin and lightly doped. With the emitter-base junction forward biased and the collector-base junction reverse biased, most carriers from the emitter cross the base to the collector, so a small base current controls a large collector current. In the common emitter configuration this gives current, voltage and power gain.","f":[{"x":"I_E = I_B + I_C","n":"Emitter current is the sum of base and collector currents.","r":"Balbharati Physics XII, 16.4, p.359"},{"x":"beta_DC = I_C/I_B","n":"Current gain in common emitter (typically 20-200).","r":"Balbharati Physics XII, 16.4, p.359"},{"x":"alpha_DC = I_C/I_E","n":"Current gain in common base (slightly less than 1).","r":"Balbharati Physics XII, 16.4, p.359"},{"x":"beta = alpha/(1 - alpha)","n":"Link between the two gains; also alpha = beta/(1 + beta).","r":"Balbharati Physics XII, 16.4, p.359"},{"x":"A_v = -beta_AC*R_L/r_i","n":"Voltage gain of a common emitter amplifier; the minus sign means output is 180 degrees out of phase.","r":"Balbharati Physics XII, 16.4, p.361"},{"x":"A_p = beta_AC*A_v","n":"Power gain (magnitude).","r":"Balbharati Physics XII, 16.4, p.361"}],"w":["A transistor does not create power: the extra output power comes from the DC supply.","The arrow in the symbol is on the emitter and points the way conventional current flows: out for n-p-n, in for p-n-p."]},"16.5":{"s":"A logic gate is a digital circuit with one or more inputs and one output, each either high (1) or low (0). The NOT gate inverts its input. The OR gate gives 1 if any input is 1; the AND gate gives 1 only if all inputs are 1. NAND and NOR are the opposites of AND and OR; they are universal gates, since any gate can be built from them. The XOR gate gives 1 when its inputs differ.","f":[{"x":"Y = NOT X","n":"NOT gate (inverter): the output is the opposite of the input.","r":"Balbharati Physics XII, 16.5, p.362"},{"x":"Y = A + B","n":"OR gate (logical addition): 1 + 1 = 1.","r":"Balbharati Physics XII, 16.5, p.362"},{"x":"Y = A·B","n":"AND gate (logical multiplication): 1 only if both inputs are 1.","r":"Balbharati Physics XII, 16.5, p.362"},{"x":"Y = NOT(A·B)","n":"NAND gate: AND followed by NOT.","r":"Balbharati Physics XII, 16.5, p.362"},{"x":"Y = NOT(A + B)","n":"NOR gate: OR followed by NOT.","r":"Balbharati Physics XII, 16.5, p.362"},{"x":"C = A ⊕ B","n":"XOR gate: 1 when exactly one input is 1.","r":"Balbharati Physics XII, 16.5, p.363"}],"w":["In Boolean algebra + means OR and a dot means AND; 1 + 1 = 1.","NAND and NOR are universal gates; AND, OR and XOR are not."]}};
